fn remove_kth_element(list: &Vec<i32>, k: usize) -> Vec<i32> {
    // Preconditions (per problem statement): 1 <= k < n, where n = list.len().
    // If you want runtime enforcement, uncomment the assert.
    // assert!(k >= 1 && k < list.len());

    let n = list.len();
    let mut new_list = Vec::with_capacity(n - 1);

    // k is 1-based; remove element at 0-based index (k - 1).
    let prefix_end = k - 1;

    new_list.extend_from_slice(&list[..prefix_end]); // elements before k
    new_list.extend_from_slice(&list[k..]);          // elements after k

    new_list
}